// Command gen writes a Go file that declares the version it is given, for
// the fixtures' go:generate directives.
package main

import (
	"flag"
	"fmt"
	"log"
	"os"
)

func main() {
	out := flag.String("o", "", "the file to write")
	version := flag.String("v", "", "the version")
	flag.Parse()
	code := fmt.Sprintf("// Code generated by internal/gen; DO NOT EDIT.\n\npackage %s\n\n// Version is the version internal/gen was given.\nconst Version = %q\n",
		os.Getenv("GOPACKAGE"), *version)
	if err := os.WriteFile(*out, []byte(code), 0o644); err != nil {
		log.Fatal(err)
	}
}
